public static MwmsProcessTransferJournalLine Construct(Name _processName = staticMethodStr(TFMConstants, TransferJournalLine), AddUpdate _addOrUpdate = AddUpdate::Update)
{
    return new MwmsProcessTransferJournalLine(_processName, _addOrUpdate);
}

protected void new(Name _processName = staticMethodStr(TFMConstants, TransferJournalLine), AddUpdate _addOrUpdate = AddUpdate::Update)
{
    processName = _processName;
    super();
    MwmsProcessTagCountingJournalLine::createBlocksSetup(_addOrUpdate, this, MwmsLogicBlockCreateTransferJournalLine::Construct(), MwmsLogicBlockCreateTransferJournalLicensePlateLine::Construct());

}
